# Grok Bot environment backup

Self-contained: a first run needs nothing else. Read settings from memory; if any is missing, run getting-started.

## 0. Settings (one set per destination)
Each destination is its own run, for example work and personal:
- `OWNER_LABEL`: name of the run, for example `work`. `BACKUP_DIR`: `/workspace/grokbot-backup`. `BACKUP_TZ`: the owner's time zone.
- Drive folder id and the Drive connector that owns it. Never upload one run's files through another run's connector.
- `INCLUDE_BOTS`, `EXCLUDE_BOTS`: comma lists of bot names or ids. `NEW_BOTS`: `include` in exactly one run and `exclude` in the others, so a new bot lands on one side only.
- `SHARED`: `1` if global settings, user skills and software lists go along (usually the work run), else `0`.
- `KEEP_HEALTH_BOTS`: bots whose health memories are kept, only in a personal run. `RETENTION_DAYS`: default 30.

Never copy or upload passwords, tokens, cookies, login files, keychain items, secret files or browser profiles.

## 1. Script
If `$BACKUP_DIR/run-backup.sh` is missing or differs from the block below, save the old one as `run-backup.sh.bak-YYYY-MM-DD`, write this one and `chmod +x` it. It stages with tar from an allowlist (user skills included; `sand-subagent-*` logs, platform skills and secret files left out), blanks sensitive store.db fields, redacts transcript tokens as `[REDACTED:type]`, drops HR, pay, performance and health memories, `chmod 600`s a readable `chrome-cookie-seed.json`, and fails on any secret outside transcripts. Reruns are safe; set `ARCHIVE_NAME` since archives are never overwritten.

```bash
#!/usr/bin/env bash
# Grok Bot backup v3. Usage: OWNER_LABEL=x BACKUP_DIR=/workspace/d [step 0 env vars] ./run-backup.sh [YYYY-MM-DD]
set -euo pipefail
DATE="${1:-$(date +%F)}"; L="${OWNER_LABEL:?set OWNER_LABEL}"; ROOT="${BACKUP_DIR:?set BACKUP_DIR}"
S="${AGENT_DATA:-/home/box/agent-data}"; HB="${BOX_HOME:-/home/box}"; B="$ROOT/$L"; IN="$ROOT/inputs/$L"; T="$B.staging"
export DATE BACKUP_TZ="${BACKUP_TZ:-UTC}" INCLUDE_BOTS="${INCLUDE_BOTS:-}" EXCLUDE_BOTS="${EXCLUDE_BOTS:-}" NEW_BOTS="${NEW_BOTS:-include}" KEEP_HEALTH_BOTS="${KEEP_HEALTH_BOTS:-}" SHARED="${SHARED:-1}"
ARCHIVE="${ARCHIVE_NAME:-grokbot-backup-$L-$DATE.tar.gz}"; [ -e "$ROOT/$ARCHIVE" ] && { echo "archive $ARCHIVE exists, refusing to overwrite" >&2; exit 1; }
while IFS= read -r f; do [ -n "$(find "$f" -perm /077)" ] && chmod 600 "$f" && echo "chmod 600 $f"; done < <(find "$HB" "$S" -maxdepth 3 -name chrome-cookie-seed.json 2>/dev/null)
X=(--exclude='*secret*' --exclude=gateway.json --exclude='store.db*' --exclude='*.lock' --exclude='*cookie*' --exclude='Login Data*' --exclude='sand-subagent-*' --exclude=chrome-profile --exclude='*key*.json' --exclude='search-index.db*')
tcp(){ local s="$1" d="$2" r=(); shift 2; for p in "$@"; do [ -e "$s/$p" ] && r+=("$p"); done; [ ${#r[@]} -gt 0 ] || return 0; mkdir -p "$d"; tar -C "$s" "${X[@]}" -cf - "${r[@]}" | tar -C "$d" -xf -; }
rm -rf "$T"; mkdir -p "$T/agent"; set +o pipefail  # no pipefail: head/tail exit 141
for A in "$S"/agents/*/; do tcp "$A" "$T/agent/$(basename "$A")" profile.json settings.json avatar.png automations attachments assets; done
if [ "$SHARED" = 1 ]; then
  tcp "$S" "$T/shared" settings.json agents/active-agent.json workflows; tcp "$HB" "$T/shared/home" .bashrc .profile reference .cursor/skills-cursor
  (cd "$S" && ls -1 managed-skills/skills plugins/cache/*/ 2>/dev/null) > "$T/shared/platform-skills-and-plugins.txt" || :
  for d in "$HB"/.cursor/projects/*/agent-transcripts; do [ -d "$d" ] && tcp "$HB/.cursor/projects" "$T/agent-transcripts" "$(basename "$(dirname "$d")")/agent-transcripts"; done
  mkdir -p "$T/software"; dpkg-query -W > "$T/software/apt.txt" 2>/dev/null || :; pip list --format=freeze > "$T/software/pip.txt" 2>/dev/null || :; npm ls -g --depth=0 > "$T/software/npm.txt" 2>&1 || :
  { uname -a; cat /etc/os-release; python3 -V; node -v; } > "$T/software/system.txt" 2>&1 || :; (cd "$HB" && find . -maxdepth 4 -not -path './chrome-profile*' -not -path './.cache/*' | sort) > "$T/software/home-tree.txt" || :
fi
cp "$IN"/bot-exports.md "$IN"/transcripts-*.md "$T/" 2>/dev/null || :; cp "$IN/connectors.md" "$T/" 2>/dev/null || cp "$ROOT/connectors.md" "$T/" 2>/dev/null || :
DEVR=$(ls -1 "$ROOT"/device-roster/grokbot-roster-*.md 2>/dev/null | sort | tail -1); [ -z "$DEVR" ] || cp "$DEVR" "$T/"; set -o pipefail
python3 - "$S" "$T" "$DEVR" <<'PY'
import json,os,re,sys,glob,sqlite3,datetime as dt,shutil
from zoneinfo import ZoneInfo
S,T,DEVR=sys.argv[1:4]; E=os.environ; TZ=ZoneInfo(E['BACKUP_TZ']); DATE=E['DATE']
def ld(p):
    try: return json.load(open(p))
    except Exception: return {}
def lst(k): return {x.strip().lower() for x in E[k].split(',') if x.strip()}
INC,EXC,KH=lst('INCLUDE_BOTS'),lst('EXCLUDE_BOTS'),lst('KEEP_HEALTH_BOTS')
def tm(ms): return dt.datetime.fromtimestamp(ms/1000,TZ).strftime('%Y-%m-%d %H:%M %Z') if ms else None
bots=[]
for A in sorted(glob.glob(f'{S}/agents/*/')):
    i=os.path.basename(A[:-1]); p=ld(A+'profile.json'); n=p.get('name') or i; k={i.lower(),n.lower()}
    st='excluded' if k&EXC else 'included' if k&INC else 'new, '+E['NEW_BOTS']+'d'
    bots.append(dict(id=i,name=n,desc=(p.get('description') or '').strip(),st=st,A=A,new=st[:3]=='new'))
for b in bots:
    if b['st'].endswith('excluded'): shutil.rmtree(f"{T}/agent/{b['id']}",ignore_errors=True)
keep=[b for b in bots if b['st'].endswith('included')]
P=[('private-key',r'-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?(?:-----END [A-Z ]*PRIVATE KEY-----|$)'),('bearer',r'(?i)\bbearer\s+([\w.~+/=-]{16,})'),
 ('jwt',r'\beyJ[\w-]{8,}\.[\w-]{8,}\.[\w-]{8,}'),('api-key',r'\b(?:sk|pk|rk)-[\w-]{16,}'),('github',r'\bgh[pousr]_\w{20,}'),('slack',r'\bxox[abprs]-[\w-]{10,}'),
 ('aws',r'\bAKIA[0-9A-Z]{16}\b'),('google-key',r'\bAIza[\w-]{30,}'),
 ('password',r'(?i)\\*"(?:password|passwd|pwd)\\*"\s*:\s*\\*"((?!\[RED)[^"\\]{3,})'),
 ('secret-field',r'(?i)\b(?:api[_-]?key|secret|access[_-]?token|refresh[_-]?token|auth[_-]?token|client[_-]?secret|password)\b\\*"?\s*[:=]\s*\\*"?((?!\[RED)[\w./+=-]{8,})')]
P=[(n,re.compile(r)) for n,r in P]
def redact(s,h):
    for n,r in P:
        def f(m,n=n):
            h[n]=h.get(n,0)+1; t=f'[REDACTED:{n}]'
            return m.group(0)[:m.start(1)-m.start()]+t+m.group(0)[m.end(1)-m.start():] if r.groups else t
        s=r.sub(f,s)
    return s
def scan(s): return sorted({n for n,r in P if r.search(s)})
SENS=re.compile(r'(?i)key|secret|token|password|cookie|credential')
def red(o):
    if isinstance(o,dict): return {k:('[redacted]' if SENS.search(k) and v not in('',None) else red(v)) for k,v in o.items()}
    if isinstance(o,list): return [red(v) for v in o]
    if isinstance(o,str) and o[:1] in '{[':
        try: return json.dumps(red(json.loads(o)))
        except Exception: pass
    return o
chats={}; day=[]
for b in keep:
    db=b['A']+'store.db'
    if not os.path.exists(db): continue
    c=sqlite3.connect(f'file:{db}?mode=ro',uri=True); out={}
    for (t,) in c.execute("select name from sqlite_master where type='table' and name!='blobs'"): out[t]=[list(r) for r in c.execute(f'select * from "{t}"')]
    for r in out.get('kv',[]):
        if SENS.search(str(r[0])): r[1]='[redacted]'; continue
        try: d=red(json.loads(bytes.fromhex(r[1]).decode())); r[1]=json.dumps(d).encode().hex(); r.append(d)
        except Exception: pass
    h={}
    for r in out.get('transcript_entries',[]):
        r[-1]=redact(r[-1],h)
        try:
            e=json.loads(r[-1]); ms=e.get('timestampMs',0)
            if ms and tm(ms)[:10]==DATE: day.append((b['name'],ms,e.get('text') or json.dumps(e.get('event') or e.get('kind'))[:2000]))
        except Exception: pass
    if h: chats[b['name']+' (box store)']=h
    out={t:(v if t=='transcript_entries' else red(v)) for t,v in out.items()}
    json.dump(out,open(f"{T}/agent/{b['id']}/store-export.json",'w'),indent=1,default=str)
for p in glob.glob(f'{T}/agent/*/*.json'):
    if not p.endswith('store-export.json'): json.dump(red(ld(p)),open(p,'w'),indent=1)
if not glob.glob(f'{T}/transcripts-*.md'):
    o=[f'# Transcripts {DATE} ({E["BACKUP_TZ"]})\nFrom box store.db only.\n']
    for b in keep: o.append(f"\n## {b['name']}\n"+(''.join(f'- {tm(m)}: {t}\n' for n,m,t in sorted(day) if n==b['name']) or 'No entries on the box for this day.\n'))
    open(f'{T}/transcripts-{DATE}.md','w').write(''.join(o))
MEM={'hr':r'\b(HR|PIP)\b|(?i:\b(human resources|hiring|fired|terminat\w+|disciplin\w+|grievance|layoffs?)\b)','pay':r'(?i)\b(salar\w+|pay ?rate|payroll|compensation|bonus\w*|raises?|wages?|stock options)\b',
 'performance':r'(?i)\b(performance (review|rating|plan|improvement)|perf review|underperform\w*)\b','health':r'(?i)\b(health|medical|diagnos\w+|medication|prescri\w+|therap\w+|doctor|symptoms?|illness|pregnan\w+|disabilit\w+|surgery)\b'}
MEM={k:re.compile(v) for k,v in MEM.items()}; dropped={}; be=f'{T}/bot-exports.md'
if os.path.exists(be):
    o=[]; bot=''; mem=False
    for ln in open(be):
        m=re.match(r'(#+)\s*(.*)',ln)
        if m: bot=m[2].lower() if len(m[1])<=2 else bot; mem='memor' in m[2].lower()
        elif mem and ln.lstrip()[:1] in '-*':
            ks=[k for k,r in MEM.items() if r.search(ln) and not (k=='health' and any(x in bot for x in KH))]
            for k in ks: dropped[k]=dropped.get(k,0)+1
            if ks: continue
        o.append(ln)
    open(be,'w').write(''.join(o))
R=[f'# Bot roster\nExtracted {dt.datetime.now(TZ):%Y-%m-%d %H:%M %Z}. {len(keep)} of {len(bots)} bots in this backup.\n']
for b in keep:
    md={}
    try: md=json.loads(bytes.fromhex(sqlite3.connect(f"file:{b['A']}store.db?mode=ro",uri=True).execute("select value from kv where key='metadata'").fetchone()[0]).decode())
    except Exception: pass
    R.append(f"\n## {b['name']}\n- Id: {b['id']}\n- Created: {tm(md.get('createdAt')) or 'not available'}\n- Description: {b['desc'] or '_empty_'}\n")
open(f'{T}/roster.md','w').write(''.join(R))
bad=[]
def walk(o,f,pa=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if SENS.search(k) and v not in('[redacted]','',None): bad.append(f'{f}:{pa}/{k}: sensitive field')
            walk(v,f,pa+'/'+k)
    elif isinstance(o,list): [walk(v,f,pa) for v in o]
for d,_,fs in os.walk(T):
    for f in fs:
        p=os.path.join(d,f); rel=os.path.relpath(p,T)
        if re.search(r'(?i)secret|cookie|login data|gateway\.json',f): bad.append(rel+': secret file'); continue
        try: s=open(p,encoding='utf-8').read()
        except Exception: continue
        if (rel.startswith('agent-transcripts/') or rel.startswith('transcripts-')) and scan(s):
            o=[]
            for part in re.split(r'(?m)^(?=## )',s):
                h={}; o.append(redact(part,h))
                if h: chats[part.splitlines()[0].lstrip('# ') if rel.endswith('.md') else rel]=h
            s=''.join(o); open(p,'w').write(s)
        if rel.startswith('agent/') and f.endswith('.json'):
            j=ld(p); j.pop('transcript_entries',None) if isinstance(j,dict) else 0; walk(j,rel); s=json.dumps(j)
        if scan(s): bad.append(rel+': '+', '.join(scan(s)))
if bad: sys.exit('SECRET CHECK FAILED (outside transcripts), nothing archived:\n'+'\n'.join(bad))
new=[b['name']+' ('+b['st']+')' for b in bots if b['new'] and (INC or EXC)]
if new: print('NEW BOTS not in INCLUDE_BOTS or EXCLUDE_BOTS:',', '.join(new))
for c,h in chats.items(): print(f'REDACTED in chat: {c}: '+', '.join(f'{k} x{v}' for k,v in h.items()))
cl=''.join(f'- {c}: '+', '.join(f'{k} x{v}' for k,v in h.items())+'\n' for c,h in chats.items()) or 'none\n'
open(f'{T}/README.md','w').write(f"""# Grok Bot backup {DATE}
Bots: {', '.join(b['name'] for b in keep) or 'none'}. Shared skills and settings: {'yes' if E['SHARED']=='1' else 'no'}. New bots default to: {E['NEW_BOTS']}.
Device roster: {os.path.basename(DEVR) if DEVR else 'missing; run the Mac roster script and upload the result to the backup folder'}.
Memories filtered: {', '.join(f'{k} {v}' for k,v in dropped.items()) or 'none'}.

## Chats with redacted tokens (replace any that are still live)
{cl}Layout: agent/<bot id>/, shared/ (settings, user skills in workflows/), roster.md, bot-exports.md, transcripts-*.md.
""")
print('secret check passed')
PY
rm -rf "$B"; mv "$T" "$B"; cd "$ROOT"; tar czf "$ARCHIVE" "$L"; ls -la "$ROOT/$ARCHIVE"
find "$ROOT" -maxdepth 1 -name "grokbot-backup-$L-*.tar.gz" -mtime +"${RETENTION_DAYS:-30}" -delete
```

## 2. Nightly steps (repeat per destination)
1. Download the newest `grokbot-roster-*.md` from the backup folder itself, not a dated subfolder, into `$BACKUP_DIR/device-roster/`.
2. In `$BACKUP_DIR/inputs/$OWNER_LABEL/` write, for included bots only: `connectors.md` (name, type, status; no secrets), `bot-exports.md` (`## <bot name>` per bot with routine prompts, sidebar section and a `### Memories` bullet list, or "not available"), and `transcripts-YYYY-MM-DD.md` (`## <bot name>` per chat) from the transcript tool. Without one, skip it; the script uses store.db.
3. Run the script with the step 0 settings as env vars. If it fails, stop and tell the owner why.
4. Create `YYYY-MM-DD` in the Drive folder if needed and upload the archive, README.md, roster.md, bot-exports.md and transcripts with UploadFile. Add `-v2` if a name is taken; never overwrite. Check each upload with `get_file_metadata` on the returned id (name and size); folder listings lag.
5. Trash dated `YYYY-MM-DD` folders older than `RETENTION_DAYS`. Touch nothing else.
6. Message the owner only on failure, a `REDACTED in chat` or `NEW BOTS` line (name the chats so live tokens get replaced; ask where new bots go), a disconnected connector, or a device roster missing for several nights.

## 3. Device roster from the owner's Mac
Sidebar sections, pinned bots, voices and local permission settings live only in the desktop app. Offer the owner this script. They run it in Terminal with `bash extract-grokbot-roster.sh` (add `--debug` to print each decoded cache name and its field names and types, never values; it needs Python 3), check the resulting `grokbot-roster-YYYY-MM-DD.md`, and upload it to the backup folder itself, not a dated subfolder. It only reads files, never reads chat transcripts, skips cookie, login, token, secret and keychain files, redacts secret-looking values, and lists anything it couldn't find. Auto-review settings are kept in the Grok Bot account, not on the Mac, so the server backup covers them.

```bash
#!/usr/bin/env bash
# Export a Grok Bot roster from the desktop app's local cache on macOS. Read-only.
# Usage: bash extract-grokbot-roster.sh [--debug] [output-dir]   -> grokbot-roster-YYYY-MM-DD.md
# --debug prints each decoded blob name and its value shape (field names and types, never values) to stderr.
# Never opens cookies, Login Data, token/secret/credential files, transcripts, or the keychain. Secret-looking values are redacted.
set -euo pipefail
DEBUG=0; OUT_DIR="$PWD"; for a in "$@"; do case "$a" in --debug) DEBUG=1;; *) OUT_DIR="$a";; esac; done; command -v python3 >/dev/null || { echo "python3 required (xcode-select --install)" >&2; exit 1; }
exec python3 - "$OUT_DIR" "$DEBUG" <<'PY'
import os,sys,json,re,sqlite3,datetime,glob,base64,gzip,zlib,struct
out_dir=sys.argv[1]; DEBUG=sys.argv[2]=='1'; H=os.path.expanduser('~')
ROOTS=[f'{H}/.grokbot']+glob.glob(f'{H}/Library/Application Support/*rok*ot*')+glob.glob(f'{H}/Library/Application Support/*rokbot*')
ROOTS=sorted({r for r in ROOTS if os.path.isdir(r)})
SKIP_NAME=re.compile(r'(?i)\.transcript\.|weekly-usage|sand-secrets|gateway-descriptor|local-exec-daemon|trust tokens|cookie|login data|token|secret|credential|keychain|password|passkey|web data|\.pem$|\.key$|\.p12$')
SKIP_DIR=re.compile(r'(?i)^(cache|code cache|gpucache|dawn.*cache|blob_storage|service worker|crashpad|logs?|node_modules|extensions|local storage|session storage|indexeddb|partitions|trust tokens)$')
SENS_KEY=re.compile(r'(?i)key|secret|token|password|cookie|credential|auth|session')
SENS_VAL=re.compile(r'(?i)(bearer\s+\S+|eyJ[\w-]{10,}\.[\w-]+\.[\w-]+|\b(sk|pk|xox[abp]|ghp|gho)[-_][\w-]{10,}|[0-9a-f]{40,})')
def red(s): return SENS_VAL.sub('[redacted]',str(s))
docs=[]  # (source, obj)
def addjson(src,txt):
    try: o=json.loads(txt)
    except Exception:
        try: o=json.loads(bytes.fromhex(txt).decode())
        except Exception: return
    if isinstance(o,(dict,list)): docs.append((src,o))
scanned=[]
SETTINGS=f'{H}/.grokbot/settings.json'; local_settings={}
try:
    local_settings=json.load(open(SETTINGS,encoding='utf-8')); scanned.append(SETTINGS)
    print(f'read {SETTINGS} ({os.path.getsize(SETTINGS)} bytes)',file=sys.stderr)
except FileNotFoundError: print(f'{SETTINGS} not found',file=sys.stderr)
except Exception as e: print(f'could not read {SETTINGS}: {e}',file=sys.stderr)
def b32name(f):
    n=f[:-5] if f.endswith('.blob') else f
    try: return base64.b32decode(n.upper()+'='*(-len(n)%8)).decode('utf-8')
    except Exception: return None
def decode_blob(raw):
    tries=[('json',lambda b:b),('gzip',gzip.decompress),('zlib',zlib.decompress),('raw-deflate',lambda b:zlib.decompress(b,-15))]
    for k in (1,2,4,8):
        tries.append((f'{k}-byte prefix',lambda b,k=k:b[k:]))
        tries.append((f'{k}-byte prefix+gzip',lambda b,k=k:gzip.decompress(b[k:])))
        tries.append((f'{k}-byte prefix+zlib',lambda b,k=k:zlib.decompress(b[k:])))
    for name,fn in tries:
        try:
            o=json.loads(fn(raw).decode('utf-8'))
            if isinstance(o,(dict,list)): return name,o
        except Exception: pass
    return None,None
for R in ROOTS:
    for d,dirs,files in os.walk(R):
        dirs[:]=[x for x in dirs if not SKIP_DIR.match(x) and not SKIP_NAME.search(x)]
        for f in files:
            p=os.path.join(d,f)
            if SKIP_NAME.search(f) or f.startswith('Singleton') or os.path.islink(p) or not os.path.isfile(p): continue
            try:
                if os.path.getsize(p)>50_000_000: continue
            except OSError: continue
            if p==SETTINGS: continue
            if f.endswith('.blob') and os.path.basename(d)=='sand-client-persistence':
                nm=b32name(f); sz=os.path.getsize(p)
                print(f'blob {nm or "(undecodable name: "+f+")"} {sz} bytes',file=sys.stderr)
                if nm is None or SKIP_NAME.search(nm): print('  skipped (secret-looking or undecodable name)',file=sys.stderr); continue
                fmt_,o=decode_blob(open(p,'rb').read())
                if o is None: print('  could not decode as JSON/gzip/zlib/prefixed',file=sys.stderr); continue
                print(f'  format: {fmt_}',file=sys.stderr)
                if DEBUG:
                    def shape(x,d=0):
                        if d>3: return '...'
                        if isinstance(x,dict): return '{'+', '.join(f'{k}: {shape(v,d+1)}' for k,v in list(x.items())[:25])+'}'
                        if isinstance(x,list): return f'list[{len(x)}] of '+(shape(x[0],d+1) if x else 'nothing')
                        return type(x).__name__
                    tgt=o.get('value',o) if isinstance(o,dict) else o
                    print(f'  [debug] {nm}: value shape: {shape(tgt)}',file=sys.stderr)
                if isinstance(o,dict) and 'value' in o and 'schemaVersion' in o: o=o['value']
                docs.append((f'blob:{nm}',o)); scanned.append(p); continue
            if f=='Preferences' or f.endswith('.json'):
                try: addjson(p,open(p,encoding='utf-8',errors='ignore').read()); scanned.append(p)
                except Exception: pass
            elif re.search(r'\.(db|sqlite3?)$',f):
                try:
                    c=sqlite3.connect(f'file:{p}?mode=ro&immutable=1',uri=True); scanned.append(p)
                    for (t,) in c.execute("select name from sqlite_master where type='table'"):
                        if SENS_KEY.search(t): continue
                        cols=[r[1] for r in c.execute(f'pragma table_info("{t}")')]
                        for row in c.execute(f'select * from "{t}" limit 20000'):
                            rk=dict(zip(cols,row))
                            for k,v in rk.items():
                                if isinstance(v,bytes):
                                    try: v=v.decode()
                                    except Exception: continue
                                if isinstance(v,str) and len(v)>1:
                                    n=len(docs); addjson(f'{p}:{t}',v)
                                    if len(docs)>n and len(cols)<=3:
                                        other=[x for x in row if isinstance(x,str) and x!=v]
                                        if other: docs[-1]=(docs[-1][0],{'__kvkey':other[0],'value':docs[-1][1]})
                except Exception as e: print(f'skip {p}: {e}',file=sys.stderr)
def walk(o,path=()):
    yield path,o
    if isinstance(o,dict):
        for k,v in o.items():
            if not SENS_KEY.search(str(k)): yield from walk(v,path+(k,))
    elif isinstance(o,list):
        for i,v in enumerate(o): yield from walk(v,path+(i,))
ID=re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
bots={}; sections=None; pinned=None; perm={}; found_src={}
def g(d,*ks):
    for k in ks:
        if isinstance(d,dict) and d.get(k) not in (None,''): return d[k]
def ts(v):
    if v in (None,'',0): return None
